import { realpath, stat } from "node:fs/promises";
import path from "node:path";
import { createGitArchive, getHeadCommit } from "./archive.js";
import { CapRoverClient } from "./caprover.js";
import { info } from "./github.js";
import { Inputs } from "./inputs.js";

export async function deploy(inputs: Inputs): Promise<void> {
  const client = new CapRoverClient(inputs.server, inputs.token);

  info("Deploying to CapRover");
  info("");
  info(`App:       ${inputs.app}`);
  info(`Server:    ${inputs.server}`);

  if (inputs.image) {
    let gitHash = "";
    try {
      gitHash = await getHeadCommit();
    } catch {
      const candidateGitHash = (process.env.GITHUB_SHA || "").trim();
      if (/^[a-f0-9]{40}$/i.test(candidateGitHash)) gitHash = candidateGitHash;
    }
    info(`Image:     ${inputs.image}`);
    if (gitHash) info(`Commit:    ${gitHash.slice(0, 7)}`);
    info("");
    await client.deployImage(inputs.app, inputs.image, gitHash);
    return;
  }

  if (!inputs.tarFile) {
    const archive = await createGitArchive(inputs.workingDirectory);
    try {
      info("Source:    Git commit");
      info(`Commit:    ${archive.gitHash.slice(0, 7)}`);
      if (inputs.workingDirectory !== ".") {
        info(`Directory: ${inputs.workingDirectory}`);
      }
      info("");
      info("✓ Source packaged");
      await client.uploadArchive(inputs.app, archive.path, archive.gitHash);
    } finally {
      await archive.cleanup();
    }
    return;
  }

  const workspace = process.env.GITHUB_WORKSPACE || process.cwd();
  const workspacePath = await realpath(workspace);
  const requestedTarPath = path.resolve(workspacePath, inputs.tarFile);
  let tarPath: string;
  try {
    tarPath = await realpath(requestedTarPath);
    const relativeTarPath = path.relative(workspacePath, tarPath);
    if (
      relativeTarPath === ".." ||
      relativeTarPath.startsWith(`..${path.sep}`) ||
      path.isAbsolute(relativeTarPath)
    ) {
      throw new Error("path is outside the workspace");
    }
    const tarStat = await stat(tarPath);
    if (!tarStat.isFile()) throw new Error("path is not a file");
  } catch {
    throw new Error(
      `Input "tar-file" does not point to a file inside the GitHub workspace: ${requestedTarPath}`,
    );
  }
  info(`Source:    Prepared tar`);
  info(`Tar file:  ${inputs.tarFile}`);
  info("");
  await client.uploadArchive(inputs.app, tarPath, "");
}

import { execFile } from "node:child_process";
import {
  access,
  mkdtemp,
  mkdir,
  readFile,
  rm,
  writeFile,
} from "node:fs/promises";
import { tmpdir } from "node:os";
import path from "node:path";
import { promisify } from "node:util";
import { afterEach, describe, expect, it } from "vitest";
import { createGitArchive } from "../src/archive.js";

const execFileAsync = promisify(execFile);
const directories: string[] = [];

afterEach(async () => {
  await Promise.all(
    directories
      .splice(0)
      .map((directory) => rm(directory, { recursive: true, force: true })),
  );
});

describe("createGitArchive", () => {
  it("archives a ref and supports spaces and special characters in paths", async () => {
    const repository = await mkdtemp(path.join(tmpdir(), "repo with spaces-"));
    directories.push(repository);
    await execFileAsync("git", ["init"], { cwd: repository });
    await execFileAsync("git", ["config", "user.email", "test@example.com"], {
      cwd: repository,
    });
    await execFileAsync("git", ["config", "user.name", "Test"], {
      cwd: repository,
    });
    await mkdir(path.join(repository, "dir [special]"));
    await writeFile(
      path.join(repository, "dir [special]", "hello world.txt"),
      "hello",
    );
    await execFileAsync("git", ["add", "."], { cwd: repository });
    await execFileAsync("git", ["commit", "-m", "fixture"], {
      cwd: repository,
    });

    const archive = await createGitArchive(".", repository);
    expect(archive.gitHash).toMatch(/^[a-f0-9]{40}$/);
    await expect(access(archive.path)).resolves.toBeUndefined();

    const { stdout } = await execFileAsync("tar", ["-tf", archive.path]);
    expect(stdout).toContain("dir [special]/hello world.txt");

    await archive.cleanup();
    await expect(access(archive.path)).rejects.toThrow();
  });

  it("archives a working directory with its contents at the tar root", async () => {
    const repository = await mkdtemp(path.join(tmpdir(), "monorepo-"));
    directories.push(repository);
    await execFileAsync("git", ["init"], { cwd: repository });
    await execFileAsync("git", ["config", "user.email", "test@example.com"], {
      cwd: repository,
    });
    await execFileAsync("git", ["config", "user.name", "Test"], {
      cwd: repository,
    });
    await mkdir(path.join(repository, "apps", "my api"), { recursive: true });
    await writeFile(path.join(repository, "root.txt"), "root");
    await writeFile(
      path.join(repository, "apps", "my api", "captain-definition"),
      "{}",
    );
    await execFileAsync("git", ["add", "."], { cwd: repository });
    await execFileAsync("git", ["commit", "-m", "fixture"], {
      cwd: repository,
    });

    const archive = await createGitArchive("apps/my api", repository);
    const { stdout } = await execFileAsync("tar", ["-tf", archive.path]);
    expect(stdout).toContain("captain-definition");
    expect(stdout).not.toContain("apps/my api");
    expect(stdout).not.toContain("root.txt");
    await archive.cleanup();
  });

  it("cleans its temporary directory when archiving fails", async () => {
    const repository = await mkdtemp(path.join(tmpdir(), "bad-repo-"));
    directories.push(repository);
    await execFileAsync("git", ["init"], { cwd: repository });
    await expect(createGitArchive("missing", repository)).rejects.toThrow(
      'Failed to archive input "working-directory" (missing)',
    );
    expect(
      await readFile(path.join(repository, ".git", "HEAD"), "utf8"),
    ).toBeTruthy();
  });
});

import { createServer, IncomingMessage } from "node:http";
import { mkdtemp, rm, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import path from "node:path";
import { afterEach, describe, expect, it } from "vitest";
import { CapRoverClient } from "../src/caprover.js";

interface CapturedRequest {
  url: string;
  headers: IncomingMessage["headers"];
  body: Buffer;
}

const directories: string[] = [];
const closers: Array<() => Promise<void>> = [];

afterEach(async () => {
  await Promise.all(closers.splice(0).map((close) => close()));
  await Promise.all(
    directories
      .splice(0)
      .map((directory) => rm(directory, { recursive: true, force: true })),
  );
});

async function startServer(
  response: object = { status: 101, description: "Build started" },
): Promise<{ url: string; request: Promise<CapturedRequest> }> {
  let resolveRequest!: (request: CapturedRequest) => void;
  const captured = new Promise<CapturedRequest>((resolve) => {
    resolveRequest = resolve;
  });
  const server = createServer((request, result) => {
    const chunks: Buffer[] = [];
    request.on("data", (chunk) => chunks.push(Buffer.from(chunk)));
    request.on("end", () => {
      resolveRequest({
        url: request.url || "",
        headers: request.headers,
        body: Buffer.concat(chunks),
      });
      result.setHeader("content-type", "application/json");
      result.end(JSON.stringify(response));
    });
  });
  await new Promise<void>((resolve) => server.listen(0, "127.0.0.1", resolve));
  closers.push(
    () => new Promise<void>((resolve) => server.close(() => resolve())),
  );
  const address = server.address();
  if (!address || typeof address === "string")
    throw new Error("Missing address");
  return {
    url: `http://127.0.0.1:${address.port}`,
    request: captured,
  };
}

describe("CapRoverClient", () => {
  it.each(["", "/"])(
    "uploads an archive with a server URL suffix of %j",
    async (suffix) => {
      const fixture = await mkdtemp(path.join(tmpdir(), "caprover archive-"));
      directories.push(fixture);
      const archivePath = path.join(fixture, "deploy file.tar");
      await writeFile(archivePath, "archive-content");
      const server = await startServer();

      await new CapRoverClient(
        `${server.url}${suffix}`,
        "app-token",
      ).uploadArchive("my-api", archivePath, "abc123");
      const request = await server.request;

      expect(request.url).toBe("/api/v2/user/apps/appData/my-api?detached=1");
      expect(request.headers["x-captain-app-token"]).toBe("app-token");
      expect(request.headers["x-namespace"]).toBe("captain");
      expect(request.headers["content-type"]).toContain("multipart/form-data");
      expect(request.body.toString()).toContain("archive-content");
      expect(request.body.toString()).toContain("abc123");
    },
  );

  it("sends the CLI-compatible image payload", async () => {
    const server = await startServer({ status: 100 });
    await new CapRoverClient(server.url, "token").deployImage(
      "my-api",
      "ghcr.io/acme/api:sha",
      "a".repeat(40),
    );
    const request = await server.request;
    const payload = JSON.parse(request.body.toString());
    expect(JSON.parse(payload.captainDefinitionContent)).toEqual({
      schemaVersion: 2,
      imageName: "ghcr.io/acme/api:sha",
    });
    expect(payload.gitHash).toBe("a".repeat(40));
  });

  it("propagates a useful CapRover API error", async () => {
    const server = await startServer({
      status: 1106,
      description: "App token is invalid",
    });
    await expect(
      new CapRoverClient(server.url, "bad-token").deployImage(
        "app",
        "image",
        "",
      ),
    ).rejects.toThrow(
      "CapRover rejected the deployment (status 1106): App token is invalid",
    );
  });

  it("rejects when the CapRover response is interrupted", async () => {
    const server = createServer((request, response) => {
      request.resume();
      request.on("end", () => {
        response.writeHead(200, { "content-type": "application/json" });
        response.write('{"status":');
        setImmediate(() => response.destroy());
      });
    });
    await new Promise<void>((resolve) =>
      server.listen(0, "127.0.0.1", resolve),
    );
    closers.push(
      () => new Promise<void>((resolve) => server.close(() => resolve())),
    );
    const address = server.address();
    if (!address || typeof address === "string")
      throw new Error("Missing address");

    await expect(
      new CapRoverClient(
        `http://127.0.0.1:${address.port}`,
        "token",
      ).deployImage("app", "image", ""),
    ).rejects.toThrow(/CapRover response (was aborted|failed)/);
  });
});

import { beforeEach, describe, expect, it, vi } from "vitest";
import * as github from "../src/github.js";
