import { execFile } from "node:child_process";
import { mkdtemp, realpath, rm, stat } from "node:fs/promises";
import { tmpdir } from "node:os";
import path from "node:path";
import { promisify } from "node:util";

const execFileAsync = promisify(execFile);

export interface TemporaryArchive {
  path: string;
  gitHash: string;
  cleanup: () => Promise<void>;
}

export async function getHeadCommit(
  workspace = process.env.GITHUB_WORKSPACE || process.cwd(),
): Promise<string> {
  const { stdout } = await execFileAsync("git", ["rev-parse", "HEAD"], {
    cwd: workspace,
  });
  const gitHash = stdout.trim();
  if (!/^[a-f0-9]{40}$/.test(gitHash)) {
    throw new Error(`git rev-parse returned an invalid commit: ${gitHash}`);
  }
  return gitHash;
}

export async function createGitArchive(
  workingDirectory: string,
  workspace = process.env.GITHUB_WORKSPACE || process.cwd(),
): Promise<TemporaryArchive> {
  const directory = await mkdtemp(path.join(tmpdir(), "caprover-deploy-"));
  const archivePath = path.join(directory, "deploy.tar");

  try {
    const workspacePath = await realpath(workspace);
    const sourcePath = await realpath(
      path.resolve(workspacePath, workingDirectory),
    );
    const sourceStat = await stat(sourcePath);
    const relativeSource = path.relative(workspacePath, sourcePath);
    if (
      !sourceStat.isDirectory() ||
      relativeSource === ".." ||
      relativeSource.startsWith(`..${path.sep}`) ||
      path.isAbsolute(relativeSource)
    ) {
      throw new Error(
        "must resolve to a directory inside the GitHub workspace",
      );
    }

    const treeRef = relativeSource
      ? `HEAD:${relativeSource.split(path.sep).join("/")}`
      : "HEAD";
    await execFileAsync(
      "git",
      ["archive", "--format=tar", "--output", archivePath, treeRef],
      { cwd: workspacePath },
    );
    const gitHash = await getHeadCommit(workspacePath);

    return {
      path: archivePath,
      gitHash,
      cleanup: () => rm(directory, { recursive: true, force: true }),
    };
  } catch (error) {
    await rm(directory, { recursive: true, force: true });
    const message = error instanceof Error ? error.message : String(error);
    throw new Error(
      `Failed to archive input "working-directory" (${workingDirectory}): ${message}`,
    );
  }
}

function escapeCommandData(value: string): string {
  return value.replace(/%/g, "%25").replace(/\r/g, "%0D").replace(/\n/g, "%0A");
}

export function getInput(name: string): string {
  const key = `INPUT_${name.replace(/ /g, "_").toUpperCase()}`;
  return process.env[key] || "";
}

export function setSecret(value: string): void {
  process.stdout.write(`::add-mask::${escapeCommandData(value)}\n`);
}

export function info(message: string): void {
  process.stdout.write(`${message}\n`);
}

export function setFailed(message: string): void {
  process.stderr.write(`::error::${escapeCommandData(message)}\n`);
  process.exitCode = 1;
}

import { createReadStream } from "node:fs";
import http from "node:http";
import https from "node:https";
import FormData from "form-data";

const SUCCESS = new Set([100, 101]);
const REQUEST_INACTIVITY_TIMEOUT_MS = 5 * 60 * 1000;

interface ApiResponse {
  status?: number;
  description?: string;
  data?: unknown;
}

export class CapRoverClient {
  private readonly baseUrl: string;

  constructor(
    server: string,
    private readonly token: string,
  ) {
    this.baseUrl = `${server.replace(/\/+$/, "")}/api/v2`;
  }

  async uploadArchive(
    app: string,
    archivePath: string,
    gitHash: string,
  ): Promise<void> {
    const form = new FormData();
    form.append("sourceFile", createReadStream(archivePath));
    form.append("gitHash", gitHash);
    await this.request(app, form, form.getHeaders());
  }

  async deployImage(
    app: string,
    imageName: string,
    gitHash: string,
  ): Promise<void> {
    const body = JSON.stringify({
      captainDefinitionContent: JSON.stringify({
        schemaVersion: 2,
        imageName,
      }),
      gitHash,
    });
    await this.request(app, body, {
      "content-type": "application/json",
      "content-length": Buffer.byteLength(body).toString(),
    });
  }

  private request(
    app: string,
    body: FormData | string,
    bodyHeaders: Record<string, string>,
  ): Promise<void> {
    const url = new URL(
      `${this.baseUrl}/user/apps/appData/${encodeURIComponent(app)}?detached=1`,
    );
    const transport = url.protocol === "https:" ? https : http;

    return new Promise((resolve, reject) => {
      const request = transport.request(
        url,
        {
          method: "POST",
          headers: {
            "x-captain-app-token": this.token,
            "x-namespace": "captain",
            ...bodyHeaders,
          },
        },
        (response) => {
          const chunks: Buffer[] = [];
          response.on("error", (error) =>
            reject(new Error(`CapRover response failed: ${error.message}`)),
          );
          response.on("aborted", () =>
            reject(new Error("CapRover response was aborted")),
          );
          response.on("data", (chunk) => chunks.push(Buffer.from(chunk)));
          response.on("end", () => {
            const responseBody = Buffer.concat(chunks).toString("utf8");
            let parsed: ApiResponse;
            try {
              parsed = responseBody ? JSON.parse(responseBody) : {};
            } catch {
              reject(
                new Error(
                  `CapRover returned an invalid response (HTTP ${response.statusCode}): ${responseBody.slice(0, 500)}`,
                ),
              );
              return;
            }

            if (
              response.statusCode === undefined ||
              response.statusCode < 200 ||
              response.statusCode >= 300
            ) {
              reject(
                new Error(
                  `CapRover request failed (HTTP ${response.statusCode}): ${parsed.description || responseBody || "No response body"}`,
                ),
              );
              return;
            }

            if (!parsed.status || !SUCCESS.has(parsed.status)) {
              reject(
                new Error(
                  `CapRover rejected the deployment (status ${parsed.status ?? "unknown"}): ${parsed.description || "No description provided"}`,
                ),
              );
              return;
            }
            resolve();
          });
        },
      );
      request.on("error", (error) =>
        reject(new Error(`Unable to reach CapRover: ${error.message}`)),
      );
      request.setTimeout(REQUEST_INACTIVITY_TIMEOUT_MS, () =>
        request.destroy(
          new Error("CapRover request was inactive for 5 minutes"),
        ),
      );

      if (typeof body === "string") {
        request.end(body);
      } else {
        body.on("error", (error) => request.destroy(error));
        body.pipe(request);
      }
    });
  }
}

import { getInput, setSecret } from "./github.js";
import path from "node:path";

export interface Inputs {
  server: string;
  app: string;
  token: string;
  image: string;
  tarFile: string;
  workingDirectory: string;
}

function readRequiredInput(name: "server" | "app" | "token"): string {
  const value = getInput(name).trim();
  if (!value) {
    throw new Error(`Input \"${name}\" is required`);
  }
  return value;
}

export function getInputs(): Inputs {
  const token = [REDACTED]"token");
  setSecret(token);

  const server = readRequiredInput("server");
  try {
    const url = new URL(server);
    if (url.protocol !== "http:" && url.protocol !== "https:")
      throw new Error();
  } catch {
    throw new Error('Input "server" must be a valid HTTP or HTTPS URL');
  }

  const image = getInput("image").trim();
  const tarFile = getInput("tar-file").trim();
  const normalizedWorkingDirectory = path.normalize(
    getInput("working-directory").trim() || ".",
  );
  const workingDirectory =
    normalizedWorkingDirectory === `.${path.sep}`
      ? "."
      : normalizedWorkingDirectory;

  if (image && tarFile) {
    throw new Error('Inputs "image" and "tar-file" cannot be used together');
  }
  if ((image || tarFile) && workingDirectory !== ".") {
    throw new Error(
      'Input "working-directory" can only be used for source deployment',
    );
  }

  return {
    server,
    app: readRequiredInput("app"),
    token,
    image,
    tarFile,
    workingDirectory,
  };
}
